    companion object {
        
    /**
     * Paths come from the same resolution as the Tauri app (`FLTS_CONFIG_DIR`
     * and friends included), so both shells open the same library.
     */
    @Throws(CoreException::class) fun `start`(`shell`: Shell): FltsCore {
            return FfiConverterTypeFltsCore.lift(
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_flts_ffi_fn_constructor_fltscore_start(
    
        
        FfiConverterTypeShell.lower(`shell`),_status)
}
    )
    }
    

        
    /**
     * For platforms without HOME (Android): the app's own directories.
     */
    @Throws(CoreException::class) fun `startWithDirs`(`shell`: Shell, `configDir`: kotlin.String, `cacheDir`: kotlin.String, `dataDir`: kotlin.String): FltsCore {
            return FfiConverterTypeFltsCore.lift(
    uniffiRustCallWithError(CoreException) { _status ->
    UniffiLib.uniffi_flts_ffi_fn_constructor_fltscore_start_with_dirs(
    
        
        FfiConverterTypeShell.lower(`shell`),
        FfiConverterString.lower(`configDir`),
        FfiConverterString.lower(`cacheDir`),
        FfiConverterString.lower(`dataDir`),_status)
}
    )
    }
    

        
