public typealias Number = Int

/**
 * @suppress
 */
public object FfiConverterTypeNumber: FfiConverter<Number, Long> {
    override fun lift(value: Long): Number {
        val builtinValue = FfiConverterLong.lift(value)
        return builtinValue.toInt()
    }

    override fun lower(value: Number): Long {
        val builtinValue = value.toLong()
        return FfiConverterLong.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): Number {
        val builtinValue = FfiConverterLong.read(buf)
        return builtinValue.toInt()
    }

    override fun allocationSize(value: Number): ULong {
        val builtinValue = value.toLong()
        return FfiConverterLong.allocationSize(builtinValue)
    }

    override fun write(value: Number, buf: ByteBuffer) {
        val builtinValue = value.toLong()
        FfiConverterLong.write(builtinValue, buf)
    }
}





public typealias Uuid = UUID


/**
 * @suppress
 */
public object FfiConverterTypeUuid: FfiConverter<Uuid, RustBuffer.ByValue> {
    override fun lift(value: RustBuffer.ByValue): Uuid {
        val builtinValue = FfiConverterString.lift(value)
        return UUID.fromString(builtinValue)
    }

    override fun lower(value: Uuid): RustBuffer.ByValue {
        val builtinValue = value.toString()
        return FfiConverterString.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): Uuid {
        val builtinValue = FfiConverterString.read(buf)
        return UUID.fromString(builtinValue)
    }

    override fun allocationSize(value: Uuid): ULong {
        val builtinValue = value.toString()
        return FfiConverterString.allocationSize(builtinValue)
    }

    override fun write(value: Uuid, buf: ByteBuffer) {
        val builtinValue = value.toString()
        FfiConverterString.write(builtinValue, buf)
    }
}









